var testHeaderSubmissionV3SSZ, _ = hex.DecodeString("")

func TestUnmarshalHeaderSubmissionV3JSON(t *testing.T) {
	expectedURL := "http://10.0.0.113:8080"
	expectedTxCount := uint32(100)
	expectedSlot := uint64(4119478)
	expectedBlockNumber := uint64(3716606)
	expectedBlockHash := phase0.Hash32(common.HexToHash("0x2165fab735f3a81b357500da98073fa0a29b01e27e8e649937d14ac9970be651"))

	versionedSubmission := new(HeaderSubmissionV3)
	err := json.Unmarshal([]byte(testHeaderSubmissionV3JSON), versionedSubmission)
	assert.NoError(t, err)

	bidTrace, err := versionedSubmission.Submission.BidTrace()
	assert.NoError(t, err)

	executionPayloadHeader, err := versionedSubmission.Submission.ExecutionPayloadHeader()
	assert.NoError(t, err)

	executionRequests, err := versionedSubmission.Submission.ExecutionRequests()
	assert.NoError(t, err)

	commitments, err := versionedSubmission.Submission.Commitments()
	assert.NoError(t, err)

	assert.Equal(t, expectedURL, string(versionedSubmission.URL))
	assert.Equal(t, expectedTxCount, versionedSubmission.TxCount)
	assert.Equal(t, expectedSlot, bidTrace.Slot)
	assert.Equal(t, expectedBlockNumber, executionPayloadHeader.BlockNumber)
	assert.Equal(t, expectedBlockHash, executionPayloadHeader.BlockHash)
	assert.Empty(t, executionRequests.Deposits)
	assert.Empty(t, executionRequests.Withdrawals)
	assert.Empty(t, executionRequests.Consolidations)
	assert.Equal(t, 1, len(commitments))
	assert.Equal(t, "0xab7868350150390c8d1d8fbd447ad8ff743c883ff11d24cc32f28d8f8f5ccb2d277aa251615b04fff46fabe666783e5a", commitments[0].String())
}

func TestUnmarshalHeaderSubmissionElectraJSON(t *testing.T) {
	expectedSlot := uint64(4119478)
	expectedBlockNumber := uint64(3716606)
	expectedBlockHash := phase0.Hash32(common.HexToHash("0x2165fab735f3a81b357500da98073fa0a29b01e27e8e649937d14ac9970be651"))

	electraSubmission := new(HeaderSubmissionElectra)
	err := json.Unmarshal([]byte(testHeaderSubmissionElectraJSON), electraSubmission)
	assert.NoError(t, err)

	assert.Equal(t, expectedSlot, electraSubmission.BidTrace.Slot)
	assert.Equal(t, expectedBlockNumber, electraSubmission.ExecutionPayloadHeader.BlockNumber)
	assert.Equal(t, expectedBlockHash, electraSubmission.ExecutionPayloadHeader.BlockHash)
	assert.Empty(t, electraSubmission.ExecutionRequests.Deposits)
	assert.Empty(t, electraSubmission.ExecutionRequests.Withdrawals)
	assert.Empty(t, electraSubmission.ExecutionRequests.Consolidations)
	assert.Equal(t, 1, len(electraSubmission.Commitments))
	assert.Equal(t, "0xab7868350150390c8d1d8fbd447ad8ff743c883ff11d24cc32f28d8f8f5ccb2d277aa251615b04fff46fabe666783e5a", electraSubmission.Commitments[0].String())
}

func TestUnmarshalHeaderSubmissionV3SSZ(t *testing.T) {
	expectedURL := "http://141.94.192.188:30300"
	expectedTxCount := uint32(17)
	expectedSlot := uint64(1225960)
	expectedBlockNumber := uint64(1138966)
	expectedBlockHash := phase0.Hash32(common.HexToHash("0xb2e8542c69fcfdb94327479b89a7eec5000d1d4817703c83231546d0a52a0119"))

	versionedSubmission := new(HeaderSubmissionV3)
	err := versionedSubmission.UnmarshalSSZ(testHeaderSubmissionV3SSZ)
	assert.NoError(t, err)

	bidTrace, err := versionedSubmission.Submission.BidTrace()
	assert.NoError(t, err)

	executionPayloadHeader, err := versionedSubmission.Submission.ExecutionPayloadHeader()
	assert.NoError(t, err)

	executionRequests, err := versionedSubmission.Submission.ExecutionRequests()
	assert.NoError(t, err)

	commitments, err := versionedSubmission.Submission.Commitments()
	assert.NoError(t, err)

	fmt.Println(executionPayloadHeader.BlockHash.String())

	assert.Equal(t, expectedURL, string(versionedSubmission.URL))
	assert.Equal(t, expectedTxCount, versionedSubmission.TxCount)
	assert.Equal(t, expectedSlot, bidTrace.Slot)
	assert.Equal(t, expectedBlockNumber, executionPayloadHeader.BlockNumber)
	assert.Equal(t, expectedBlockHash, executionPayloadHeader.BlockHash)
	assert.Empty(t, executionRequests.Deposits)
	assert.Empty(t, executionRequests.Withdrawals)
	assert.Empty(t, executionRequests.Consolidations)
	assert.Equal(t, 0, len(commitments))
}
